/* Restore JEITA < 10.0°C 0.25C derating branch in bms_step() */
if ((float)temp_c < 10.0f) {
    allowed_current = 0.8125; /* 0.25C NCR18650B cold limit */
    derated = 1;
}

/* Enforce unconditional 1-tick contactor opening on NTC sensor fault */
if (temp_sensor_fail != 0) {
    out->commanded_current_a = 0.0;
    out->contactor_state = 0x01;
    out->fault_code = 1;
    return;
}
